<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Tagihan', href: '/owner/invoices' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';

    type Invoice = { id: number; invoice_number: string; due_date: string; cycle_start_date: string | null; cycle_end_exclusive: string | null; property: { id: number; name: string } | null; room: { id: number; code: string } | null; resident: { id: number; full_name: string } | null; tenancy_id: number | null; total_due_rupiah: number; paid_rupiah: number; balance_rupiah: number; status: string };
    type Page<T> = { data: T[]; links: { url: string | null; label: string; active: boolean }[]; from: number | null; to: number | null; total: number };
    let { invoices, properties, filters }: { invoices: Page<Invoice>; properties: { id: number; name: string }[]; filters: { status: string; property_id: string; tenancy_id: string } } = $props();
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
    const statusLabel: Record<string, string> = { unpaid: 'Belum dibayar', partial: 'Dibayar sebagian', paid: 'Lunas', overdue: 'Terlambat' };
</script>

<AppHead title="Tagihan" />
<main class="space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-end justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Keuangan</p><h1 class="text-3xl font-semibold tracking-tight">Tagihan</h1><p class="text-sm text-muted-foreground">Saldo dihitung dari kewajiban, penyesuaian, pembayaran, dan settlement deposit.</p></div><Link href="/owner/payments/create" class="inline-flex rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground">Catat penerimaan</Link></header>
    <Form action="/owner/invoices" method="get" class="grid gap-3 rounded-xl border bg-card p-4 sm:grid-cols-3 sm:items-end">{#snippet children({ processing })}<div class="space-y-1"><label for="status" class="text-sm font-medium">Status</label><select id="status" name="status" value={filters.status} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua status</option><option value="unpaid">Belum dibayar</option><option value="partial">Dibayar sebagian</option><option value="overdue">Terlambat</option><option value="paid">Lunas</option></select></div><div class="space-y-1"><label for="property_id" class="text-sm font-medium">Properti</label><select id="property_id" name="property_id" value={filters.property_id} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Semua properti</option>{#each properties as property (property.id)}<option value={property.id}>{property.name}</option>{/each}</select></div><Button type="submit" disabled={processing}>Terapkan filter</Button>{/snippet}</Form>
    <section class="overflow-hidden rounded-xl border bg-card shadow-sm" aria-label="Daftar tagihan">
        {#if invoices.data.length === 0}<div class="p-10 text-center"><h2 class="font-medium">Belum ada tagihan</h2><p class="mt-1 text-sm text-muted-foreground">Tagihan sewa dibuat saat check-in dan dilanjutkan otomatis setiap siklus bulanan.</p></div>{:else}<div class="overflow-x-auto"><table class="w-full min-w-[58rem] text-left text-sm"><thead class="border-b bg-muted/40 text-muted-foreground"><tr><th class="px-5 py-3 font-medium">Tagihan / penyewa</th><th class="px-5 py-3 font-medium">Properti / kamar</th><th class="px-5 py-3 font-medium">Jatuh tempo</th><th class="px-5 py-3 font-medium">Status</th><th class="px-5 py-3 text-right font-medium">Sisa</th><th class="px-5 py-3 text-right font-medium">Aksi</th></tr></thead><tbody class="divide-y">{#each invoices.data as invoice (invoice.id)}<tr><td class="px-5 py-4"><p class="font-medium">{invoice.invoice_number}</p><p class="mt-1 text-xs text-muted-foreground">{invoice.resident?.full_name ?? '—'}</p></td><td class="px-5 py-4"><p>{invoice.property?.name ?? '—'}</p><p class="text-xs text-muted-foreground">{invoice.room ? `Kamar ${invoice.room.code}` : '—'}</p></td><td class="px-5 py-4">{invoice.due_date}</td><td class="px-5 py-4"><span class="rounded-full border px-2.5 py-1 text-xs">{statusLabel[invoice.status] ?? invoice.status}</span></td><td class="px-5 py-4 text-right font-medium">{money(invoice.balance_rupiah)}</td><td class="px-5 py-4 text-right"><Link href={`/owner/invoices/${invoice.id}`} class="text-primary underline-offset-4 hover:underline">Detail</Link></td></tr>{/each}</tbody></table></div><footer class="flex flex-wrap items-center justify-between gap-4 border-t px-5 py-4 text-sm"><p class="text-muted-foreground">Menampilkan {invoices.from ?? 0}–{invoices.to ?? 0} dari {invoices.total} tagihan</p><nav aria-label="Navigasi halaman" class="flex flex-wrap gap-1">{#each invoices.links as link, index (index)}{#if link.url}<Link href={link.url} class={`rounded border px-3 py-1.5 ${link.active ? 'bg-primary text-primary-foreground' : 'hover:bg-muted'}`}>{link.label}</Link>{:else}<span class="rounded border px-3 py-1.5 text-muted-foreground">{link.label}</span>{/if}{/each}</nav></footer>{/if}
    </section>
</main>
